    "content": "中新网10月1日电 据中央气象台网站消息，昨日，重庆、贵州、湖北、湖南、浙江等地出现较强降雨，内蒙古、华北、东北等地出现大风降温天气。预计未来三天，青藏高原东部至南方大部地区多阴雨天气，贵州、重庆、湖南等局地有强降雨，关注对交通、旅游安全的不利影响；今日较强冷空气继续影响东部地区，内蒙古、华北、东北及东海等海域风力大，黄淮、江汉、江南等地降温明显；明日起，新一股冷空气影响，中东部地区有大风降温天气；关注大风降温对交通、城市运行、农牧业设施等影响。"
