    "title": "美国加州《反机器人老板》法案生效，禁止完全依赖 AI 解雇或惩戒员工",
    "link": "https://www.ithome.com/1/008/965.htm",
    "pub_date": "2026-10-01 08:14:48",
    "author": "",
    "description": "IT之家 10 月 1 日消息，IT之家 9 月 11 日消息，美国加利福尼亚州州长 Gavin Newsom（加文 · 纽森）当地时间昨日签署《2026 年反机器人老板法案》(SB 947)，对人工智能在人力资源领域的应用作出规制。 该法案禁止加州雇主完全依赖基于人工智能的自动化决策系统来解雇或惩戒员工；要求雇主在使用自动化决策系统做出解雇和惩戒决定时，必须进行人工监督和核实；要求雇主向员工披露解雇和惩戒决定中的自动化决策系统使用情况…",
