    "content": "针对澎湃新闻此前报道的云南昭通市巧家县农业农村局拖欠企业12.5万元设备采购款长达两年多未结清一事，9月30日晚间，涉事企业负责人告诉澎湃新闻，已于报道刊发后的当日傍晚收到巧家县农业农村局拨付的全部两笔欠款。 巧家县农业农村局相关负责人证实，在收到澎湃新闻情况反馈后，该局立即和企业沟通，原计划在10月8日拨付欠款，后经多方协调推进，已于当日下午完成欠款清偿。 9月10日，有企业在巧家县人民政府官网留言投诉，巧家县农业农村局分别于2024年4月30日、5月8日在政采云平台采购两笔国产办公设备，合同总金额12.5万元。…"
