    "author": "sudo123",
    "description": "从 Brave 切换到 Catsxp 了，主要原因有几点： 1 、Brave 的本地优化版，作者是中国人。一些小细节优化得比较好，比如垂直标签有树状结构。砍掉了 VPN/AI/钱包功能。AI/翻译功能装个豆包插件就完事。 2 、自带的翻译功能切换到了谷歌翻译，而不是 brave 翻译。 3 、密码/书签/扩展程序列表我用插件，不用浏览器自带的功能，可以无痛迁移。 -密码管理器（本地 Keepass+chromeIPass 浏览器插件） …",
