    "description": "",
    "content": "快科技10月1日消息，近日，重庆一对情侣国庆放假回家期间遭遇惊魂一幕。 一块巨石从十几米高空突然坠落，直接砸穿停放在路边的特斯拉车辆天窗，造成A柱、B柱受损，副驾驶车门变形无法开启。 所幸事发前两人刚好离开车辆去割草，与死神擦肩而过。 车主张女士介绍，当天她和对象放假回家，正准备上车休息时，突然想起家里的兔子没有草吃了，便喊上对象一起去割草。 就在两人离开车辆后不久，一块“超级大”的石头从十几米高的位置坠落，先是砸穿车辆天窗玻璃，随后落入副驾驶区域。 巨石的冲击力直接导致车辆A柱和B柱出现受损变形，副驾驶一侧的车门…"
