    "description": "新华社迪拜9月30日电（记者温新年 夏晓）阿联酋迪拜航空公司9月30日说，当天原定从迪拜飞往以色列特拉维夫的FZ1073航班发生驾驶舱冲突事件后，该公司已暂停所有往返以色列的航班，等待有关方面对事件展开调查。 迪拜航空在一份声明中说，这一决定是在与有关部门协调后作出的。公司将继续与政府部门、监管机构和机场方面保持密切协调，并根据进一步获得的信息对停航决定进行评估。 迪拜航空对旅行计划受到影响的乘客表示歉意，并表示正尽可能提供协助和替代出…",
    "content": "新华社迪拜9月30日电（记者温新年 夏晓）阿联酋迪拜航空公司9月30日说，当天原定从迪拜飞往以色列特拉维夫的FZ1073航班发生驾驶舱冲突事件后，该公司已暂停所有往返以色列的航班，等待有关方面对事件展开调查。 迪拜航空在一份声明中说，这一决定是在与有关部门协调后作出的。公司将继续与政府部门、监管机构和机场方面保持密切协调，并根据进一步获得的信息对停航决定进行评估。 迪拜航空对旅行计划受到影响的乘客表示歉意，并表示正尽可能提供协助和替代出行安排。 据阿联酋媒体报道，FZ1073航班当天在飞往特拉维夫途中，副驾驶涉嫌在…"
