    "description": "新华社大马士革9月30日电（记者林建杰）据叙利亚《革命报》9月30日报道，一辆客车当晚在位于叙中西部哈马省的迈斯亚夫桥上遭到不明身份人员袭击，造成7死4伤。 据叙利亚国家通讯社报道，叙过渡政府内政部安全部队和民防队伍已抵达现场进行安全管控，并转运死伤者。安全部队正在调查袭击者身份。",
