    "content": "新华社日本名古屋9月30日电（记者王沁鸥）爱知·名古屋亚运会组织工作再出纰漏。30日，名古屋市市长刚刚公开致歉，当晚电竞比赛中途断网，速度攀岩计时系统故障——都是各自比赛中罕见的情况。不过各个赛场的运动员们始终专注而进取，其中中国跳水队达成“百金”成就，电竞项目诞生首位女子冠军选手。 9月30日，练俊杰在比赛中。新华社记者 伍志尊 摄 跳水项目当日收官。奥运冠军练俊杰在男子10米台比赛中险胜，为中国队拿到本届赛事第10金。中国跳水队就此收获亚运参赛史第100金，自1974年首次参赛以来从未让金牌旁落。赛后，练俊杰表…"
