    "content": "30/09/2026 - 18:48 路透社9月30日消息，法国政府当天透露，法国正在和英国讨论终止一项协议。根据该协议，乘坐小型船只抵达英国领土的移民，将被送返至法国领土。该协议即将到期，法国政府将不再寻求延续这一协议。 巴黎和伦敦去年宣布了这一协议。该协议旨在减少穿越英吉利海峡，非法抵达英国领土的移民数量。该协议遵循“以一换一”的原则，即，每当法国接收一名被送回法国的无证移民，英国政府就会对等接收一名身处法国、并且和英国具有家庭关系的庇护申请者。 英国内政部一名发言人证实称，巴黎和伦敦之间的试点计划“已经不再受…"
