    "content": "新华社日本名古屋9月30日电（记者肖亚卓、张曼琳）30日，在爱知·名古屋亚运会电子竞技第五人格亚运版本决赛中，中国队战胜日本队，夺得该项目“入亚”后首枚金牌。中国队选手穆欣月（ID：桃晚安）成为亚运会电竞项目首位女子冠军。 9月30日，中国队选手在决赛前出场。新华社记者 王菲 摄 电竞项目虽不分男女组别，但目前仍以男性运动员为主。本届赛事共有超过500名注册运动员，其中女性仅14人。 “一开始打比赛时，我没想到自己能在亚运会舞台上拿到金牌。”穆欣月说，“当国歌响起、金牌挂在胸前时，既激动又开心，这可能是我人生中最幸…"
