    "content": "30/09/2026 - 18:30 美国众议院美国与中共战略竞争特设委员会主席、共和党籍联邦众议员穆勒纳尔（John Moolenaar）呼吁特朗普政府审视盟国——韩国与中国日益升温的关系，称这种关系对美国构成“重大风险”。 穆勒纳尔在致美国国务卿鲁比奥（Marco Rubio）的信中，敦促对韩中关系保持“高度警惕”。他列举了多项因素，包括两国领导人层面日益密切的联系、韩国在华半导体投资，以及其口中美国企业在韩国所受待遇不如中国竞争对手公平的问题。 韩国外交部表示，无法就这封信的具体内容发表评论；该信于周二寄出，…"
