    "description": "我自己是玄学爱好者，研习一个比较小众的派别，是奇门遁甲的分支。 我针对这个派别自己做了一个排盘的 app ，一直上架不了。 审核都是说已经有很多这类 app 了，让我不要再做了。可是排盘方式还是有点不一样的，只是看来都是排盘 app 而已。 这种情况应该怎么办啊。大家有经验吗。",
