    "content": "新华社马德里9月30日电（记者孟鼎博）重庆系列出版文化活动9月26日至29日在西班牙马德里和巴塞罗那举行，内容包括学术研讨、文化互动体验、阅读分享和图书展示等。 “中西新时代文明对话：中国式现代化的世界意义”国际学术研讨会26日在马德里举行。与会者围绕《中国式现代化“六观”》丛书西语版，就中国式现代化等话题展开交流。活动期间，重庆新华出版集团向西班牙共产党赠送丛书西语版，双方相关机构签署合作协议。 西班牙共产党主席森特利亚现场致辞时表示，中国式现代化是走和平发展道路的现代化。 重庆市委宣传部副部长、市政府新闻办主任…"
