    "content": "新华社北京9月30日电 世界乒乓球职业大联盟（WTT）9月30日宣布，中国选手王楚钦、林诗栋因伤退出2026年WTT中国大满贯赛，他们的正赛席位将由资格赛幸运落败者递补。 在日前结束的爱知·名古屋亚运会乒乓球项目比赛中，林诗栋和王楚钦会师男单决赛。林诗栋在决赛中以4:0获胜，成为本届亚运会混双、男双和男单“三金王”。 在二人退赛后，参加今年WTT中国大满贯赛男单正赛的国乒选手有温瑞博、周启豪、向鹏、陈垣宇、梁靖崑、陈俊菘、黄友政和薛飞。 2026年WTT中国大满贯赛将于10月1日至11日在北京石景山首钢园区进行，设…"
