    "author": "罗兰,潘志伟",
    "description": "9月30日，三峡枢纽新通道先行开挖区项目顺利完成全部爆破开挖作业。 三峡水运新通道工程包含三峡枢纽新通道和葛洲坝航运扩能两部分，三峡枢纽新通道先行开挖区是三峡水运新通道工程施工准备试验工程，其顺利完工将为后续高压输电线路迁改、船闸主体工程全面施工创造有利条件，同时也标志着三峡水运新通道工程即将迈入全面施工的新阶段。目前，三峡枢纽新通道先行开挖区施工现场情况如何？记者实地探访。 作者：罗兰、潘志伟、高于 新华社音视频部制作",
