    "author": "车云龙",
    "description": "新华社柏林9月30日电（记者车云龙）德国联邦统计局9月30日公布的初步数据显示，受能源价格大幅上涨推动，德国9月通胀率升至3.3%，高于8月的2.9%，为2023年年底以来最高水平。 数据显示，9月德国能源价格同比上涨14.9%，涨幅较8月的10.5%进一步扩大。 受中东战事导致能源价格高企等因素影响，德国通胀压力持续加大。德国五大经济研究机构日前发布联合经济预测报告，预计德国今年通胀率将由去年的2.2%升至2.8%，2027年进一步升…",
    "content": "新华社柏林9月30日电（记者车云龙）德国联邦统计局9月30日公布的初步数据显示，受能源价格大幅上涨推动，德国9月通胀率升至3.3%，高于8月的2.9%，为2023年年底以来最高水平。 数据显示，9月德国能源价格同比上涨14.9%，涨幅较8月的10.5%进一步扩大。 受中东战事导致能源价格高企等因素影响，德国通胀压力持续加大。德国五大经济研究机构日前发布联合经济预测报告，预计德国今年通胀率将由去年的2.2%升至2.8%，2027年进一步升至3.2%。 德国政府日前宣布，为缓解高油价给居民和企业带来的负担，将从10月1…"
